import{$,status,download,canvasBlob}from'./common.js';import{QRCode}from'./vendor.js';
let payload='',valid=false,revision=0;const wifiEscape=s=>s.replace(/[\\;,:"']/g,'\\$&');const cardEscape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&');
function content(){const type=$('#type').value;if(type==='url'){const u=new URL($('#url').value);if(!['http:','https:'].includes(u.protocol))throw Error('Use a website URL starting with https:// or http://.');return u.href}if(type==='wifi'){if(!$('#ssid').value.trim())throw Error('Enter a network name.');return`WIFI:T:${$('#security').value};S:${wifiEscape($('#ssid').value)};P:${$('#security').value==='nopass'?'':wifiEscape($('#password').value)};H:${$('#hiddenNetwork').checked};;`}if(!$('#name').value.trim())throw Error('Enter a contact name.');return`BEGIN:VCARD\nVERSION:3.0\nFN:${cardEscape($('#name').value)}\nEMAIL:${cardEscape($('#email').value)}\nTEL:${cardEscape($('#phone').value)}\nEND:VCARD`}
function luminance(hex){const v=hex.match(/\w\w/g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return v[0]*.2126+v[1]*.7152+v[2]*.0722}function options(){return{width:+$('#size').value,margin:4,errorCorrectionLevel:'Q',color:{dark:$('#foreground').value,light:$('#background').value}}}
async function render(){const r=++revision;['url','wifi','contact'].forEach(t=>$('#'+t+'Fields').hidden=$('#type').value!==t);try{const value=content();const fg=luminance($('#foreground').value),bg=luminance($('#background').value);if(fg>=bg||(bg+.05)/(fg+.05)<4.5)throw Error('Choose a darker code color and a lighter background with at least 4.5:1 contrast.');await QRCode.toCanvas($('#qr'),value,options());if(r!==revision)return;payload=value;valid=true;$('#payload').textContent=payload;$('#png').disabled=$('#svg').disabled=false;status('Ready to download and scan.')}catch(e){if(r!==revision)return;valid=false;$('#png').disabled=$('#svg').disabled=true;const c=$('#qr');c.getContext('2d').clearRect(0,0,c.width,c.height);$('#payload').textContent='';status(e.message,true)}}
document.querySelectorAll('input,select').forEach(e=>e.oninput=render);$('#png').onclick=async()=>{if(!valid)return;download(await canvasBlob($('#qr')),'qr-studio.png');status('PNG downloaded.')};$('#svg').onclick=async()=>{if(!valid)return;try{const svg=await QRCode.toString(payload,{...options(),type:'svg'});download(new Blob([svg],{type:'image/svg+xml'}),'qr-studio.svg');status('SVG downloaded.')}catch(e){status(e.message,true)}};render();
